    if (!sending) submit(action);
    else if (form.dataset.liveAction === "answer") queuedPick = action;
    else if (form.dataset.liveAction === "winners") queuedPrizes.push(action);
  });

  const cable = window.ActionCable?.createConsumer();
  cable?.subscriptions.create({ channel: "GameUpdatesChannel", code: root.dataset.liveCode }, {
    connected() {
      streaming = true;
      sync(); // Also catch up on changes missed before subscribing/reconnecting.
    },
    received: sync,
    disconnected() {
